import 'package:flutter/material.dart';
import '../main.dart';
import '../desktop/resource_settings.dart';
import '../desktop/resource_monitor.dart';

class ResourceSettingsScreen extends StatefulWidget {const ResourceSettingsScreen({super.key});@override State<ResourceSettingsScreen> createState()=>_ResourceSettingsScreenState();}
class _ResourceSettingsScreenState extends State<ResourceSettingsScreen>{final r=ResourceSettings.instance;
Widget slider(String key,String title,double min,double max,double step){final current=(r.get(key) as num).toDouble();return Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('$title: ${current.toStringAsFixed(0)}%'),Slider(min:min,max:max,divisions:((max-min)/step).round(),activeColor:gold,value:current,onChanged:(v){if(key=='criticalRam'&&v>=(r.get('lowRam') as num)){r.set(key,((r.get('lowRam') as num)-2).clamp(0,20).toDouble());}else if(key=='lowRam'&&(r.get('criticalRam') as num)>=v){r.set('lowRam',v);r.set('criticalRam',(v-2).clamp(2,20).toDouble());return;}r.set(key,v);})]);}
@override Widget build(BuildContext context)=>AnimatedBuilder(animation:r,builder:(context,_)=>ListView(padding:const EdgeInsets.all(12),children:[const ResourceMonitor(),DropdownButtonFormField<String>(value:r.get('profile') as String,decoration:const InputDecoration(labelText:'Profile'),items:['Battery Saver','Balanced','Performance','Custom'].map((e)=>DropdownMenuItem(value:e,child:Text(e))).toList(),onChanged:(v){if(v!=null&&v!='Custom')r.profile(v);}),slider('lowRam','Low RAM warning',5,40,1),slider('criticalRam','Critical RAM',2,20,1),slider('lowStorage','Low Storage warning',5,30,1),slider('highCpu','High CPU warning',60,95,1),slider('batterySaver','Battery saver threshold',5,40,1),slider('criticalBattery','Critical battery threshold',2,20,1),_windowsSlider(),SwitchListTile(value:r.get('autoMinimize') as bool,activeColor:gold,title:const Text('Auto-minimize oldest window'),onChanged:(v)=>r.set('autoMinimize',v)),SwitchListTile(value:r.get('autoLite') as bool,activeColor:gold,title:const Text('Auto Lite Mode when low RAM'),onChanged:(v)=>r.set('autoLite',v)),SwitchListTile(value:r.get('autoBatterySaver') as bool,activeColor:gold,title:const Text('Auto Battery Saver'),onChanged:(v)=>r.set('autoBatterySaver',v)),_dropdown('Background Window Sleep Time','sleepTime',['1min','5min','10min','Never']),_dropdown('Refresh rate','refreshRate',['1s','2s','5s']),FilledButton(onPressed:()=>r.reset(),child:const Text('Reset to Default'))]));
Widget _windowsSlider(){final key=(r.get('liteMode') as bool)?'maxWindowsLite':'maxWindowsNormal';final v=r.get(key) as int;return Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Max Windows (${(r.get('liteMode') as bool)?'Lite':'Normal'}): $v'),Slider(min:1,max:8,divisions:7,activeColor:gold,value:v.toDouble(),onChanged:(x)=>r.set(key,x.round()))]);}
Widget _dropdown(String label,String key,List<String> choices)=>DropdownButtonFormField<String>(value:r.get(key) as String,decoration:InputDecoration(labelText:label),items:choices.map((s)=>DropdownMenuItem(value:s,child:Text(s))).toList(),onChanged:(v){if(v!=null)r.set(key,v);});
}

